CREATE TABLE IF NOT EXISTS certificates ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, course_version_id TEXT NOT NULL REFERENCES course_versions(id), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'issued', 'revoked')), recipient_name TEXT NOT NULL CHECK (length(recipient_name) BETWEEN 1 AND 120), course_title TEXT NOT NULL, final_score_pct REAL, completed_at INTEGER NOT NULL, certificate_no TEXT UNIQUE CHECK (certificate_no IS NULL OR length(certificate_no) <= 80), verification_code TEXT UNIQUE CHECK (verification_code IS NULL OR length(verification_code) = 16), verify_url TEXT, issued_at INTEGER, sync_attempts INTEGER NOT NULL DEFAULT 0, next_retry_at INTEGER, last_error TEXT CHECK (last_error IS NULL OR length(last_error) <= 300), revoked_at INTEGER, revoked_by TEXT, revoked_reason TEXT CHECK (revoked_reason IS NULL OR length(revoked_reason) <= 300), UNIQUE (user_id, course_id), CHECK (status <> 'issued' OR (certificate_no IS NOT NULL AND verification_code IS NOT NULL)) );
CREATE INDEX IF NOT EXISTS ix_certificates_course ON certificates(course_id);
CREATE INDEX IF NOT EXISTS ix_certificates_sync ON certificates(status, next_retry_at);
CREATE TABLE IF NOT EXISTS d1_migrations (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
INSERT OR IGNORE INTO d1_migrations (name) VALUES ('0003_certificates.sql');
